package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.provider.DocumentsContract;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** MyBible and USX use the same private staging database and atomic publication as text imports. */
final class BibleModuleWork {
 static final long MAX_COPY=268435456L;static final int MAX_FILES=1000;
 static void folder(Activity a,Uri tree,String title,int flags){ImportWork.permission(a,tree,flags);PlusUi.run(a,()->{String id;try(TaskStore tasks=new TaskStore(a)){id=tasks.create("bible","Importar Bíblia USX · "+title,new JSONObject().put("tree",tree.toString()).put("title",title).put("name","Pasta USX").put("mime","inode/directory"));Uri document=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));tasks.getWritableDatabase().insertOrThrow("scan_nodes",null,StudyStore.values("job",id,"uri",document.toString()));}TaskService.launch(a,id);});}
 static String format(Context c,JSONObject d)throws Exception{if(d.has("tree"))return "folder";String name=d.getString("name").toLowerCase(Locale.ROOT);if(name.endsWith(".search"))throw new IOException("Este ficheiro é um índice de pesquisa MyBible. Seleccione o .SQLite3 correspondente, sem .search.");if(name.matches(".*\\.(sqlite3|sqlite|db)$"))return "sqlite";if(name.endsWith(".usx")||name.endsWith(".xml"))return "usx";if(name.endsWith(".zip"))return "zip";if(name.matches(".*\\.(ldml|vrs|jpg|jpeg|png)$"))throw new IOException("Este ficheiro é uma configuração ou capa. Escolha uma Bíblia .SQLite3, um livro USX ou a pasta USX_1.");String kind=MediaFormats.kind(d.getString("name"),d.getString("mime"));if(!kind.equals("epub")&&!kind.equals("pdf")&&!kind.equals("docx")){try(InputStream in=ApkInstallActivity.openSource(c,Uri.parse(d.getString("uri")))){byte[] h=new byte[16];if(in.read(h)==16&&Arrays.equals(h,"SQLite format 3\000".getBytes("US-ASCII")))return "sqlite";}}return "";}
 static File copy(Context c,Uri uri,File file,long limit,TaskService.Control control)throws Exception{if(!file.isFile()){File part=new File(file.getPath()+".part");if(part.exists()&&!part.delete())throw new IOException("Cópia temporária ocupada.");try(InputStream in=ApkInstallActivity.openSource(c,uri)){StudyFiles.copy(in,file,limit,control::cancelled);}}if(file.length()>limit)throw new IOException("Módulo acima do limite de tamanho.");return file;}
 static void scan(Context c,TaskStore tasks,String id,JSONObject data,TaskService.Control control)throws Exception{if(data.optBoolean("scan_complete"))return;Uri tree=Uri.parse(data.getString("tree"));int sequence=(int)tasks.count(id,null);for(;;){control.check();String node=null;try(Cursor row=tasks.getReadableDatabase().rawQuery("SELECT uri FROM scan_nodes WHERE job=? AND done=0 LIMIT 1",new String[]{id})){if(row.moveToFirst())node=row.getString(0);}if(node==null)break;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(Uri.parse(node)));try(Cursor rows=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},android.os.Bundle.EMPTY,null)){if(rows==null)throw new IOException("Sem acesso à pasta USX. Escolha-a novamente.");while(rows.moveToNext()){control.check();String name=rows.getString(1),mime=rows.getString(2);Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,rows.getString(0));if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){tasks.getWritableDatabase().insertWithOnConflict("scan_nodes",null,StudyStore.values("job",id,"uri",uri.toString()),SQLiteDatabase.CONFLICT_IGNORE);if(DatabaseUtils.longForQuery(tasks.getReadableDatabase(),"SELECT COUNT(*) FROM scan_nodes WHERE job=?",new String[]{id})>5000)throw new IOException("Seleccione apenas a pasta de uma versão USX.");}else if(name!=null&&name.toLowerCase(Locale.ROOT).matches(".*\\.(usx|xml)$")){try(Cursor prior=tasks.getReadableDatabase().rawQuery("SELECT 1 FROM items WHERE job=? AND uri=?",new String[]{id,uri.toString()})){if(prior.moveToFirst())continue;}if(sequence>=MAX_FILES)throw new IOException("Mais de 1000 ficheiros candidatos. Seleccione a pasta de uma só versão USX.");tasks.add(id,sequence++,uri.toString(),name,0,0);}}}tasks.getWritableDatabase().update("scan_nodes",StudyStore.values("done",1),"job=? AND uri=?",new String[]{id,node});control.progress("A verificar pasta USX · "+sequence+" ficheiros",0,0);}data.put("scan_complete",true);tasks.payload(id,data);if(sequence==0)throw new IOException("Não há ficheiros USX nesta pasta. Abra a pasta da versão ou USX_1; JPG, LDML e VRS não contêm os versículos.");}
 interface Parse {void run()throws Exception;}
 static void part(SQLiteDatabase stage,int next,Parse parser)throws Exception{stage.beginTransaction();try{parser.run();stage.execSQL("INSERT OR REPLACE INTO checkpoint(id,position,value) VALUES(1,?,'{}')",new Object[]{next});stage.setTransactionSuccessful();}finally{stage.endTransaction();}}
 static void read(Context c,String id,TaskStore tasks,JSONObject data,SQLiteDatabase stage,String format,BibleText.Sink sink,TaskService.Control control)throws Exception{final long[] imported={DatabaseUtils.longForQuery(stage,"SELECT COUNT(*) FROM verses",null)};final BibleText.Sink limited=(book,chapter,verse,text)->{if(++imported[0]>200000)throw new IOException("A Bíblia excede 200000 versículos. Seleccione uma só versão.");sink.verse(book,chapter,verse,text);};File root=SummaryWork.root(c,id);int first=data.optInt("next",0);final long[] lastPulse={-1000};Runnable pulse=()->{long now=android.os.SystemClock.elapsedRealtime();if(now-lastPulse[0]<400)return;lastPulse[0]=now;long count=DatabaseUtils.longForQuery(stage,"SELECT COUNT(*) FROM verses",null);control.progress("A ler módulo bíblico · "+count+" versículos",0,1);};
  if(format.equals("folder")){scan(c,tasks,id,data,control);int total=(int)tasks.count(id,null);long cached=0;File[] files=root.listFiles();if(files!=null)for(File f:files)if(f.getName().startsWith("usx-")&&!f.getName().endsWith(".part"))cached+=f.length();for(int index=first;index<total;index++){control.check();StudyStore.Row item=tasks.items(id,null,index,1).get(0);File file=new File(root,"usx-"+index+".xml");if(!file.isFile()){file=copy(c,Uri.parse(item.s("uri")),file,Math.min(33554432,MAX_COPY-cached),control);cached+=file.length();}final File source=file;final int at=index;part(stage,index+1,()->{boolean usx=item.s("name").toLowerCase(Locale.ROOT).endsWith(".usx");if(!usx)try(InputStream in=new FileInputStream(source)){usx=BibleUsx.isUsx(in);}if(usx)try(InputStream in=new FileInputStream(source)){BibleUsx.read(in,limited,control::cancelled,()->control.progress("USX · "+item.s("name")+" · "+(at+1)+" / "+total,at,total));}});data.put("next",index+1);tasks.payload(id,data);control.progress("A importar pasta USX · "+(index+1)+" / "+total,index+1,total);}}
  else{File source=copy(c,Uri.parse(data.getString("uri")),new File(root,"module-input.bin"),MAX_COPY,control);String hash=StudyFiles.hash(source);if(data.has("module_hash")&&!hash.equals(data.getString("module_hash")))throw new IOException("A cópia do módulo foi alterada. Inicie uma nova importação.");data.put("module_hash",hash);tasks.payload(id,data);
   if(format.equals("sqlite")&&first==0)part(stage,1,()->BibleMyBible.read(source,limited,control::cancelled,pulse));
   else if(format.equals("usx")&&first==0)part(stage,1,()->{try(InputStream in=new FileInputStream(source)){BibleUsx.read(in,limited,control::cancelled,pulse);}});
   else if(format.equals("zip")){try(ZipFile zip=new ZipFile(source)){if(zip.size()>10000)throw new IOException("ZIP com demasiadas entradas. Escolha a pasta de uma versão USX.");List<ZipEntry> entries=new ArrayList<>();Enumeration<? extends ZipEntry> all=zip.entries();while(all.hasMoreElements()){ZipEntry e=all.nextElement();if(!e.isDirectory()&&e.getName().toLowerCase(Locale.ROOT).matches(".*\\.(usx|xml)$"))entries.add(e);}entries.sort(Comparator.comparing(ZipEntry::getName));if(entries.isEmpty()||entries.size()>MAX_FILES)throw new IOException("O ZIP deve conter os ficheiros de uma versão USX.");for(int i=first;i<entries.size();i++){control.check();ZipEntry entry=entries.get(i);if(entry.getSize()>33554432)throw new IOException("Livro USX acima de 32 MB.");final int at=i;part(stage,i+1,()->{boolean usx=entry.getName().toLowerCase(Locale.ROOT).endsWith(".usx");if(!usx)try(InputStream in=zip.getInputStream(entry)){usx=BibleUsx.isUsx(in);}if(usx)try(InputStream in=zip.getInputStream(entry)){BibleUsx.read(in,limited,control::cancelled,()->control.progress("USX · "+entry.getName()+" · "+(at+1)+" / "+entries.size(),at,entries.size()));}});data.put("next",i+1);tasks.payload(id,data);}}}
  }
  control.check();stage.beginTransaction();try{stage.execSQL("INSERT OR REPLACE INTO checkpoint(id,position,value) VALUES(1,-1,'{}')");stage.setTransactionSuccessful();}finally{stage.endTransaction();}
 }
 private BibleModuleWork(){}
}
